/// Every setting of the library crates this facade links: its own, then
/// core's, the Postgres backend's and the object store's.
pub fn all() -> impl Iterator<Item = &'static Setting> {
    SETTINGS
        .iter()
        .chain(proxiima_core::env::SETTINGS)
        .chain(proxiima_storage_pg::settings::SETTINGS)
        .chain(proxiima_blob_s3::settings::SETTINGS)
}

/// `rows` as the operator's Markdown table, one row per setting, in order:
/// `Setting | Purpose | When needed | Type | Default`.
///
/// ```
/// let table = proxiima::settings::markdown_table(proxiima::settings::all());
/// assert!(table.starts_with("| Setting | Purpose | When needed | Type | Default |\n"));
/// assert!(table.contains("\n| PROXIIMA_STORE_NUMBER | "));
/// ```
pub fn markdown_table<'a>(rows: impl IntoIterator<Item = &'a Setting>) -> String {
    let header = "| Setting | Purpose | When needed | Type | Default |\n|---|---|---|---|---|\n";
    let body = rows.into_iter().map(|row| {
        let default = row
            .default()
            .map(|value| format!("`{value}`"))
            .unwrap_or_default();
        format!(
            "| {} | {} | {} | {} | {default} |\n",
            row.name(),
            row.purpose(),
            row.when_needed(),
            row.kind().label(),
        )
    });
    std::iter::once(header.to_owned()).chain(body).collect()
}

/// Log one warning for each `PROXIIMA_*` variable of the process
/// environment that neither this facade nor `host` declares. Names only,
/// never values. A host may define names of its own, so an unknown name is
/// reported, not refused.
pub fn warn_unknown_env<'a>(host: impl IntoIterator<Item = &'a Setting>) {
    let names: Vec<String> = std::env::vars_os()
        .map(|(name, _)| name.to_string_lossy().into_owned())
        .collect();
    let mut declared: Vec<&Setting> = all().collect();
    declared.extend(host);
    for name in unknown_names(names.iter().map(String::as_str), &declared) {
        tracing::warn!(
            variable = name,
            "environment variable {name} starts with PROXIIMA_ but is not a declared setting; it is ignored"
        );
    }
}

/// The `PROXIIMA_*` names among `names` that no row of `declared` names.
fn unknown_names<'n>(
    names: impl IntoIterator<Item = &'n str>,
    declared: &[&Setting],
) -> Vec<&'n str> {
    names
        .into_iter()
        .filter(|name| name.starts_with("PROXIIMA_"))
        .filter(|name| !declared.iter().any(|setting| setting.name() == *name))
        .collect()
}

#[cfg(test)]
mod tests {
    use super::{all, unknown_names};

    #[test]
    fn a_misspelled_proxiima_name_is_the_one_reported() {
        let declared: Vec<_> = all().collect();
        let names = [
            "PROXIIMA_STORE_NUMBR",
            "PROXIIMA_STORE_NUMBER",
            "DATABASE_URL",
            "PATH",
            "XPROXIIMA_STORE_NUMBER",
        ];
        assert_eq!(unknown_names(names, &declared), ["PROXIIMA_STORE_NUMBR"]);
    }

    #[test]
    fn every_declared_name_is_declared_once() {
        let mut names: Vec<_> = all().map(proxiima_core::Setting::name).collect();
        let count = names.len();
        names.sort_unstable();
        names.dedup();
        assert_eq!(names.len(), count, "a setting is declared in two crates");
    }
}
